def snap(pbin, blocked):
    """Nearest-open-bin snapping, mirroring decode_position_within's temp_maps cleaning."""
    if len(blocked) == 0:
        return pbin
    ob = np.setdiff1d(np.arange(9), blocked)
    co = np.stack([np.arange(9) % 3, np.arange(9) // 3], 1)
    lut = np.arange(9)
    for b in blocked:
        lut[b] = ob[np.argmin(np.linalg.norm(co[ob] - co[b], axis=1))]
    return lut[pbin]


